  // -- showInternalFactionPolitics --
  "politics_core.showInternalFactionPolitics.001":'showInternalFactionPolitics',
  "politics_core.showInternalFactionPolitics.002":(v0,v1)=>`<h2>${v0} — Internal Faction Affairs</h2><p>Trusted allies can press arguments inside a faction’s local leadership. Backing one bloc may change policy, but it can also deepen internal rivalries.</p>${v1}<div class="dialog-footer"><button id="internalPoliticsBack">Back to Local Politics</button></div>`,
  "politics_core.showInternalFactionPolitics.003":(v0,v1,v2,v3,v4,v5,v6,v7,v8)=>`<h2>${v0} — Inside ${v1}</h2><div class="notice"><b>Influence inside local leadership:</b> ${v2}<br>${v3}<br><b>Guardian standing:</b> ${v4}${v5} • <b>Political Capital:</b> ${v6}</div><h3>Internal Blocs</h3>${v7}<h3>Major Interventions</h3><div class="choice-list"><button id="internalCompromise"><b>Broker Compromise — 12 PC</b><br><small>Push the strongest blocs toward a settlement before the dispute damages the faction further.</small></button><button id="internalReassign"><b>Press for Leadership Reassignment — 22 PC</b><br><small>Requires standing 8. Shift local authority toward a chosen policy bloc.</small></button><button id="internalWithdraw"><b>Threaten Withdrawal of Guardian Support — 25 PC</b><br><small>Requires standing 10. Powerful, public, and likely to cause resentment.</small></button></div><h3>Recent Internal Developments</h3>${v8}<div class="dialog-footer"><button id="internalFactionBack">Back to Internal Faction Affairs</button></div>`,
  // -- showInternalBlocChooser --
  "politics_core.showInternalBlocChooser.001":'showInternalBlocChooser',
  "politics_core.showInternalBlocChooser.002":(v0)=>`<h2>Choose the Policy Bloc</h2><p>Which internal bloc should gain influence if this intervention succeeds?</p>${v0}<div class="dialog-footer"><button id="internalChoiceBack">Back</button></div>`,

