  // -- showFactionCivicActions --
  "politics_campaigns_civic.showFactionCivicActions.001":'showFactionCivicActions',
  "politics_campaigns_civic.showFactionCivicActions.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8)=>`<h2>${v0} — Support ${v1}</h2><div class="notice"><b>${v2} public support</b> • ${v3} organization • ${v4} legitimacy<br>Faction standing: ${v5}${v6}<br>${v7}</div><p>Build support in public through meetings, aid, organizing, endorsements, and civic work.</p><div class="choice-list">${v8}<button id="seekPoliticalEndorsement"><b>Seek a Named Resident’s Endorsement</b><br><small>Ask a familiar local contact to speak publicly for this faction.</small></button></div><div class="dialog-footer"><button id="civicFactionBack">Back to Political Activities</button></div>`,
  "politics_campaigns_civic.showFactionCivicActions.003":'townNav',
