  "politics_campaigns_civic.showIndependentCivicActions.001":'showIndependentCivicActions',
  "politics_campaigns_civic.showIndependentCivicActions.002":(v0,v1)=>`<h2>${v0} — Act Without a Faction</h2><div class="notice"><b>Local autonomy ${v1}/10</b><br>These actions help the settlement directly without giving an organized faction the public credit.</div><div class="choice-list"><button data-independentcivic="relief"><b>Fund Nonpartisan Relief</b><br><small>Food and basic aid without faction conditions • 24g</small></button><button data-independentcivic="works"><b>Fund Public Works</b><br><small>Repairs and practical improvements under local civic control • 30g</small></button><button data-independentcivic="forum"><b>Sponsor an Open Public Forum</b><br><small>Give rival positions room to argue publicly and strengthen local civic process • 12g</small></button></div><div class="dialog-footer"><button id="independentCivicBack">Back to Political Activities</button></div>`,
  // -- showPoliticalCampaignDesk --
  "politics_campaigns_civic.showPoliticalCampaignDesk.001":'showPoliticalCampaignDesk',
  "politics_campaigns_civic.showPoliticalCampaignDesk.002":(v0,v1)=>`<h2>${v0} — Faction Campaign Work</h2><p>Local faction representatives have assignments that could strengthen their position here—organizing supporters, protecting trade, building public confidence, or improving security.</p>${v1}<div class="dialog-footer"><button id="campaignDeskBack">Back to Local Politics</button></div>`,
  "politics_campaigns_civic.showPoliticalCampaignDesk.003":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10)=>`<h2>${v0} — ${v1} Campaign</h2><div class="notice"><b>Current campaign need:</b> ${v2}<br>${v3}${v4}</div><div class="stat-row"><span>Campaign momentum</span><b>${v5} (${v6})</b></div><div class="stat-row"><span>Completed commissions</span><b>${v7}</b></div><div class="stat-row"><span>Failed / abandoned</span><b>${v8}</b></div>${v9}<h3>Recent Campaign History</h3>${v10}<div class="dialog-footer"><button id="campaignFactionBack">Back to Campaign Desk</button></div>`,
  "politics_campaigns_civic.showPoliticalCampaignDesk.004":'No Commission Available',
  "politics_campaigns_civic.showPoliticalCampaignDesk.005":'The faction cannot assemble a new local campaign assignment right now.',
  "politics_campaigns_civic.showPoliticalCampaignDesk.006":'Campaign Commission Posted',
  "politics_campaigns_civic.showPoliticalCampaignDesk.007":(v0)=>`${v0} is now available on the local contract board. Local organizers will judge the effort when the assignment is completed or abandoned.`,
  "politics_campaigns_civic.showPoliticalCampaignDesk.008":(v0)=>`Goal: ${v0}.`,
  "politics_campaigns_civic.showPoliticalCampaignDesk.009":(v0)=>`Expected effect if completed: ${v0}.`,
  "politics_campaigns_civic.showPoliticalCampaignDesk.010":'townNav',
  "politics_campaigns_civic.showPoliticalCampaignDesk.011":'Dump Refuse at Rival Headquarters',
  "politics_campaigns_civic.showPoliticalCampaignDesk.012":'Pay night workers to leave carts of refuse, broken crates, and stable waste outside the rival office.',
  "politics_campaigns_civic.showPoliticalCampaignDesk.013":'Deface Rival Notices & Posters',
  "politics_campaigns_civic.showPoliticalCampaignDesk.014":'Remove, spoil, or cover the rival faction’s public notices before morning.',
  "politics_campaigns_civic.showPoliticalCampaignDesk.015":'Redirect Rival Supply Wagons',
  "politics_campaigns_civic.showPoliticalCampaignDesk.016":'Use false instructions, bribed handlers, and confused manifests to send useful supplies somewhere else.',
  "politics_campaigns_civic.showPoliticalCampaignDesk.017":'Break In & Ruin Organizing Records',
