  // -- showCovertPoliticalActions --
  "politics_covert_raids.showCovertPoliticalActions.001":'showCovertPoliticalActions',
  "politics_covert_raids.showCovertPoliticalActions.002":(v0,v1,v2,v3)=>`<h2>${v0} — Covert & Hostile Politics</h2><div class="warning notice"><b>${v1}</b> • ${v2}<br>If you are exposed, personal relationships, faction standing, local reputation, and the law may all turn against you.</div><h3>Who Benefits?</h3>${v3}<button data-covertsponsor="none"><b>No Faction</b><br><small>Act for your own reasons. Any political benefit remains unaffiliated.</small></button><div class="dialog-footer"><button id="covertBackPolitics">Back to Local Politics</button></div>`,
  "politics_covert_raids.showCovertPoliticalActions.003":(v0,v1)=>`<h2>Choose a Political Rival</h2><p>${v0}</p>${v1}<div class="dialog-footer"><button id="covertTargetBack">Back</button></div>`,
  "politics_covert_raids.showCovertPoliticalActions.004":(v0,v1,v2,v3,v4,v5,v6,v7,v8)=>`<h2>${v0} — Against ${v1}</h2><div class="warning notice"><b>Beneficiary:</b> ${v2}<br><b>Likely political hub:</b> ${v3}<br><b>Risk:</b> ${v4} • ${v5}<br><b>Legal cover:</b> ${v6}</div><div class="choice-list">${v7}<button id="politicalForceAttack"><b>Attack Rival Armed Supporters</b><br><small>Fight locally based guards or armed supporters. Very high exposure and legal risk.</small></button><button id="politicalLeaderRaid" ${v8}><b>Night Action Against a Political Leader</b><br><small>Threaten, wound, or kill a visible organizer or advocate. The consequences can be severe.</small></button></div><div class="dialog-footer"><button id="covertOpsBack">Back to Rival Selection</button></div>`,
  // -- showPoliticalSituation --
  "politics_covert_raids.showPoliticalSituation.001":'showPoliticalSituation',
  "politics_covert_raids.showPoliticalSituation.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10,v11)=>`<h2>${v0} — Political Situation</h2><div class="notice compact"><b>Formal control:</b> ${v1} • <b>Political lead:</b> ${v2}<br>Government: ${v3} • ${v4} • Local autonomy ${v5}/10<br>Road authority: ${v6} • Openness ${v7}/10${v8}</div><div class="political-profile-list">${v9}</div><h3>Recent Local Political Activity</h3>${v10}<div class="notice compact"><b>Road conditions:</b> ${v11}</div><div class="dialog-footer"><button id="politicalSituationBack">Back to Local Politics</button></div>`,
  "politics_covert_raids.showPoliticalSituation.003":'politicalSituation',
  // -- showLocalPoliticalActions --
  "politics_covert_raids.showLocalPoliticalActions.001":'showLocalPoliticalActions',
  "politics_covert_raids.showLocalPoliticalActions.002":(v0,v1)=>`<h2>${v0} — Political Activities</h2><p>Choose a faction to support publicly, or work through local civic institutions without taking a faction’s side.</p><h3>Support a Faction</h3>${v1}<h3>Act Independently</h3><button id="nonpartisanPolitics"><b>Civic Work Without Faction Sponsorship</b><small>Relief, public works and an open forum that strengthen local institutions.</small></button><div class="dialog-footer"><button id="politicalActionsBack">Back to Local Politics</button></div>`,
  "politics_covert_raids.showLocalPoliticalActions.003":'politicalActivities',

