  // -- npcPoliticalReason --
  "politics_faction_social.npcPoliticalReason.001":'Independent',
  "politics_faction_social.npcPoliticalReason.002":'Prefers local commercial control, predictable roads, and fewer outside obligations.',
  "politics_faction_social.npcPoliticalReason.003":'Redstone',
  "politics_faction_social.npcPoliticalReason.004":'Bluestone',
  "politics_faction_social.npcPoliticalReason.005":'Coalition',
  "politics_faction_social.npcPoliticalReason.006":'Shantium',
  "politics_faction_social.npcPoliticalReason.007":(v0)=>`Values organized security and the authority responsible for ${v0}.`,
  "politics_faction_social.npcPoliticalReason.008":'Wants greater local bargaining power against the current administration.',
  "politics_faction_social.npcPoliticalReason.009":'Places more weight on civic stability and practical services than on faction labels.',
  "politics_faction_social.npcPoliticalReason.010":'Judges politics mainly by food security, local stores, and whether outside demands leave households enough to get through the season.',
  "politics_faction_social.npcPoliticalReason.011":(v0)=>`Has longstanding local ties to the institutions governing ${v0}.`,
  "politics_faction_social.npcPoliticalReason.012":(v0)=>`Sees ${v0} as a useful counterweight in local affairs.`,
