  // -- factionPeopleHTML --
  "politics_faction_social.factionPeopleHTML.001":'<p class="muted">No especially visible faction-aligned people are known here.</p>',
  // -- createPoliticalRelationshipContract --
  "politics_faction_social.createPoliticalRelationshipContract.001":(v0,v1)=>`${v0} The request also carries ${v1} political implications.`,
  // -- factionSocialDailyTick --
  "politics_faction_social.factionSocialDailyTick.001":(v0)=>`named supporters and known travelers have standing in ${v0}`,
  "politics_faction_social.factionSocialDailyTick.002":(v0)=>`${v0} has become increasingly visible locally`,
  // -- showPoliticalEndorsementPeople --
  "politics_faction_social.showPoliticalEndorsementPeople.001":'showPoliticalEndorsementPeople',
  "politics_faction_social.showPoliticalEndorsementPeople.002":(v0,v1,v2)=>`<h2>${v0} — Seek ${v1} Endorsements</h2><p>Personal trust matters. Asking someone to publicly change sides can damage the relationship if the request cuts against a strong existing commitment.</p>${v2}<div class="dialog-footer"><button id="endorsementPeopleBack">Back</button></div>`,
  // -- attemptNpcPoliticalEndorsement --
  "politics_faction_social.attemptNpcPoliticalEndorsement.001":'Too Soon',
  "politics_faction_social.attemptNpcPoliticalEndorsement.002":(v0)=>`${v0} has already discussed local politics with the Guardian recently.`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.003":(v0,v1)=>`${v0} is already an active ${v1} supporter and agrees to be more visible about it.`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.004":(v0)=>`${v0} publicly reinforces an existing endorsement`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.005":(v0,v1)=>`You persuaded ${v0} that ${v1} offers the better local course`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.006":(v0)=>`${v0}'s endorsement increased the Guardian's local political influence`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.007":(v0,v1)=>`${v0} publicly endorses ${v1}`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.008":(v0,v1,v2)=>`${v0} agrees to publicly support ${v1}. People who know ${v2} now have a local face attached to that position.`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.009":(v0,v1,v2)=>`${v0} declines to endorse ${v1}. ${v2}`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.010":(v0,v1)=>`You asked ${v0} to publicly support ${v1}.`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.011":(v0,v1,v2,v3)=>`${v0}'s opinion of the Guardian ${v1} (${v2} → ${v3}).`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.012":(v0)=>`Political meeting with ${v0}`,
  "politics_faction_social.attemptNpcPoliticalEndorsement.013":'Public Endorsement',
  // -- showNpcPoliticalConversation --
  "politics_faction_social.showNpcPoliticalConversation.001":'showNpcPoliticalConversation',
  "politics_faction_social.showNpcPoliticalConversation.002":(v0,v1,v2,v3,v4,v5,v6,v7)=>`<h2>${v0} — Local Politics</h2><div class="notice"><b>${v1}: ${v2} ${v3}</b><br>${v4}</div><p>${v5} is ${v6} toward you. Familiarity and personal opinion affect how seriously they will take a request for public support.</p><div class="choice-list"><button id="npcPoliticsWhy">Ask Why</button>${v7}</div><div class="dialog-footer"><button id="npcPoliticsBack">Back to Conversation</button></div>`,
  "politics_faction_social.showNpcPoliticalConversation.003":(v0)=>`${v0} on Local Politics`,
  // -- showLocalPoliticalPeople --
  "politics_faction_social.showLocalPoliticalPeople.001":'showLocalPoliticalPeople',
  "politics_faction_social.showLocalPoliticalPeople.002":(v0,v1,v2)=>`<h2>${v0} — Local Political Voices</h2><p>Named residents can become supporters, organizers, opponents, or persuadable local figures. Their views are personal and can change as conditions and relationships change.</p>${v1}${v2}<div class="dialog-footer"><button id="localPoliticalPeopleBack">Back to Local Politics</button></div>`,
  // -- showFactionSocialNetwork --
  "politics_faction_social.showFactionSocialNetwork.001":'showFactionSocialNetwork',
  "politics_faction_social.showFactionSocialNetwork.002":'factionSocial',
  "politics_faction_social.showFactionSocialNetwork.003":(v0,v1,v2,v3,v4,v5)=>`<h2>${v0} — People & Social Influence</h2><p>These are the people whose support, opposition, and connections matter here.</p>${v1}<button id="localPoliticalVoices"><b>Named Political Voices</b><small>Residents who organize, persuade, support, or oppose local factions.</small></button><h3>Visible People</h3>${v2}${v3}<h3>Recent Changes</h3>${v4}<div class="dialog-footer"><button id="factionSocialBack">${v5}</button></div>`,
  "politics_faction_social.showFactionSocialNetwork.004":'townNav',
