  "contracts_contracts_journal.showWorldJournal.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10,v11,v12,v13,v14,v15,v16,v17,v18,v19,v20)=>`<h2>World Journal</h2><div class="journal-width-control"><label>Journal Width <input id="journalWidthRange" type="range" min="760" max="1500" step="20" value="${v0}"><output id="journalWidthValue">${v1}px</output></label><small>Large displays only • saved automatically</small></div><div class="journal-priority-grid"><div class="journal-priority-card"><b>Current Location</b><span>${v2} • ${v3} • Day ${v4}</span></div><div class="journal-priority-card"><b>Contracts</b><span>${v5} ready • ${v6} active${v7}</span></div><div class="journal-priority-card"><b>Story</b><span>${v8} active regional stor${v9} • ${v10} resolved</span></div><div class="journal-priority-card"><b>World Life</b><span>${v11} actionable item${v12} • ${v13} recent movement${v14}</span></div></div>${v15}${v16}${v17}<div class="journal-group-stack"><section class="journal-group"><h3>Work & Story</h3><div class="journal-section-grid"><button id="journalHubContracts"><b>Contracts</b><small>Active work, turn-ins & history</small></button><button id="journalHubStories"><b>Regional Stories</b><small>Authored arcs & outcomes</small></button></div></section><section class="journal-group"><h3>People & Company</h3><div class="journal-section-grid"><button id="journalHubCompanions"><b>Companions</b><small>Road life, social connections & expeditions</small></button><button id="journalHubWorldLife"><b>World Life</b><small>Contacts, social events, movement & referrals</small></button></div></section><section class="journal-group"><h3>Region & Resources</h3><div class="journal-section-grid"><button id="journalHubRegions"><b>Regions & Politics</b><small>Conditions, factions, law & opportunities</small></button><button id="journalHubEconomy"><b>Economy & Trade</b><small>Holdings, markets & interregional signals</small></button><button id="journalHubExploration"><b>Exploration</b><small>Sites, artifacts & encounters</small></button></div></section><section class="journal-group"><h3>Records</h3><div class="journal-section-grid"><button id="journalHubHistory"><b>World History</b><small>Major campaign consequences</small></button><button id="journalHubArchive"><b>Full Journal Archive</b><small>Detailed legacy journal view</small></button><button id="journalJavascriptErrorsAlways"><b>JavaScript Errors</b><small>Runtime diagnostics • ${v18} recorded</small></button></div></section></div>${v19}<h3>Latest Regional News</h3>${v20}<div class="dialog-footer"><button class="closeModal">Close</button></div>`,
