  "economy_property_investments.showEconomyLedger.001":'showEconomyLedger',
  "economy_property_investments.showEconomyLedger.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10)=>`<h2>Company Economy</h2><div class="notice"><b>${v0} properties</b> • Lifetime property income ${v1}g • ${v2} active caravan investment${v3}</div><h3>Accounts</h3>${v4}<h3>Holdings</h3>${v5}<h3>Caravan Investments</h3>${v6}<h3>Trade Network</h3><button id="economyMarketIntel">Market Intelligence / Known Routes</button>${v7}<div class="stat-row"><span>Deliveries</span><b>${v8}</b></div><div class="stat-row"><span>Caravan losses</span><b>${v9}</b></div><h3>Recent Property Ledger</h3>${v10}<div class="dialog-footer"><button class="closeModal">Close</button></div>`,
