  "law_encounter_planning_law.maybeTrespassNotice.001":(v0)=>`<h2>Restricted Area</h2><div class="warning notice">${v0} challenges the company’s presence here.</div><div class="choice-list"><button id="trespassLeave">Leave Immediately</button><button id="trespassExplain">Explain Your Business</button><button id="trespassStay">Remain Anyway</button></div>`,
