  // -- showLocalLaw --
  "law_encounter_planning_law.showLocalLaw.001":'showLocalLaw',
  "law_encounter_planning_law.showLocalLaw.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10)=>`<h2>${v0} — Law & Order</h2><div class="${v1} notice"><b>${v2}</b> • ${v3}<br>Heat ${v4}/25 • Outstanding bounty ${v5}g • Restitution ${v6}g • Legal reputation ${v7}${v8}</div><h3>Recent Record</h3>${v9}${v10}<div class="dialog-footer"><button class="closeModal">Close</button></div>`,
  // -- maybeLawCheckpoint --
  "law_encounter_planning_law.maybeLawCheckpoint.001":(v0,v1,v2,v3,v4,v5,v6)=>`<h2>Stopped by ${v0}</h2><div class="warning notice">A local warrant is active. Charges total ${v1} gold${v2}.${v6?`<br><b>${v6}</b>`:""}</div><div class="choice-list"><button id="lawStopSubmit">Submit to Arrest</button><button id="lawStopPay" ${v3}>Pay Charges — ${v4}g</button>${v5}<button id="lawStopTalk">Try to Talk Your Way Through</button><button id="lawStopRun">Refuse and Flee</button></div>`,
