  // -- showRegionalLaw --
  "law_encounter_planning_law.showRegionalLaw.001":'showRegionalLaw',
  "law_encounter_planning_law.showRegionalLaw.002":(v0,v1,v2,v3,v4,v5,v6)=>`<h2>${v0} — Law & Reputation</h2><p>Charges belong to the jurisdiction that received a credible report.${v1}</p>${v2}<h3>Regional Summary</h3><div class="stat-row"><span>Fines paid</span><b>${v3}g</b></div><div class="stat-row"><span>Times jailed</span><b>${v4}</b></div><div class="stat-row"><span>Bribes attempted</span><b>${v5}</b></div><div class="stat-row"><span>Active wanted jurisdictions</span><b>${v6}</b></div><div class="dialog-footer"><button class="closeModal">Close</button></div>`,

