  "world_party_interactions.showRegionalBattle.004":(v0,v1,v2,v3)=>`<h2>Guardian Caravan Stopped</h2><p><b>${v0}</b> has stopped <b>${v1}</b> near ${v2}.</p><div class="notice compact">The patrol appears to be treating the caravan as suspicious traffic. No battle has begun yet.</div>${v3}<div class="dialog-footer"><button class="closeModal">Leave It for Now</button></div>`,
  "world_party_interactions.showRegionalBattle.005":(v0,v1,v2,v3,v4,v5,v6)=>`<h2>Battle on the Road</h2><p><b>${v0}</b> (${v1}) is fighting <b>${v2}</b> (${v3}).</p>${v4}${v5}<div class="choice-list">${v6}<button class="closeModal">Leave Them</button></div>`,
  "world_party_interactions.showRegionalBattle.006":'Observed a regional battle',
