  "world_party_interactions.showWorldParty.004":(v0,v1,v2,v3,v4,v5,v6,v7)=>`<h2>${v0}</h2><p><b>${v1}</b> • ${v2} → ${v3}</p><div class="notice">${v4}</div><div class="choice-list">${v5}${v6}${v7}<button id="partyEscortDetails">Contract Details</button><button id="worldAvoid">Close Report</button></div>`,
