  // -- adventureStoryText --
  "exploration_adventures_dungeons_factionquests.adventureStoryText.001":'<div class="success notice"><b>The Watchfort Ledger — Complete</b><br>The old frontier supply records have been recovered and delivered to Shantium.</div>',
