  "siege_campaign_start_menu.equipReturnedBoundWeapon.001":(v0)=>`Bound weapon returned and equipped: ${v0}. Its power will recover as the Guardian advances.`,
  // -- startCampaign --
  "siege_campaign_start_menu.startCampaign.001":'Siege',
  "siege_campaign_start_menu.startCampaign.002":(v0,v1)=>`Start a new ${v0} campaign?\n\nThis will overwrite the existing ${v1} save, but your other campaign mode will remain untouched.`,
  "siege_campaign_start_menu.startCampaign.003":'Unnamed Guardian',
  "siege_campaign_start_menu.startCampaign.004":(v0)=>`The first reports arrive. ${v0} takes command as Guardian of Shantium.`,
  "siege_campaign_start_menu.startCampaign.005":'There is more to defend than one person can comfortably handle.',
