  // -- showContinueFailure --
  "siege_campaign_start_menu.showContinueFailure.001":'showContinueFailure',
  "siege_campaign_start_menu.showContinueFailure.002":'Siege Mode',
  "siege_campaign_start_menu.showContinueFailure.003":'The campaign could not be prepared for play.',
  "siege_campaign_start_menu.showContinueFailure.004":(v0,v1,v2)=>`<h2>Continue Could Not Finish</h2><div class="warning notice"><b>Your ${v0} save is still present.</b><br>A compatibility problem stopped Continue. No save was deleted.</div><p class="compact">${v1}</p>${v2}<p>The game already tried the main save, automatic backup, and compatible legacy copy.</p><div class="choice-list"><button id="continueRetry">Retry Continue</button><button id="continueImport">Import Save Backup</button></div><div class="dialog-footer"><button id="continueBack">Back to Main Menu</button></div>`,
  // -- continueSavedCampaign --
  "siege_campaign_start_menu.continueSavedCampaign.001":'<b>Loading…</b><small>Checking and repairing save</small>',
  "siege_campaign_start_menu.continueSavedCampaign.002":'Continue render failed',
  "siege_campaign_start_menu.continueSavedCampaign.003":'Open World compatibility recovery',
  "siege_campaign_start_menu.continueSavedCampaign.004":'Continue recovery render failed',
  // -- renderMenu --
  "siege_campaign_start_menu.renderMenu.001":(v0,v1,v2,v3,v4,v5,v6,v7)=>`<div class="menu-screen"><div class="menu-window"><h1 class="menu-title">SIEGE OF SHANTIUM</h1><div class="menu-sub">A Macintosh-style party role-playing game</div><div class="continue-campaigns"><h3>Continue Campaign</h3><button id="continueOpenBtn" class="continue-slot continue-open" ${v0}><b>${v1}</b><small>${v2}</small></button><button id="continueSiegeBtn" class="continue-slot continue-siege" ${v3}><b>${v4}</b><small>${v5}</small></button></div><div class="notice"><b>Separate save slots:</b> one Open World campaign and one Siege campaign can be active at the same time. Continue cards now show the saved Guardian class so a stale/wrong save is visible before loading.</div><h3>Start New Campaign</h3><div class="new-form"><label>Guardian Name<input id="guardianName" maxlength="24" value="Guardian"></label><label>Difficulty<select id="difficulty">${v6}</select></label></div><div class="mode-grid"><button id="openWorldBtn" class="mode-card"><b>NEW OPEN WORLD</b><br><small>Travel, seek companions, explore the regions, and build an ongoing Guardian.</small></button><button id="siegeBtn" class="mode-card"><b>NEW SIEGE MODE</b><br><small>The condensed 12-round defense of Shantium.</small></button></div><div class="menu-actions"><button id="statsBtn">Career Statistics</button><button id="importBtn">Import Save</button><button id="helpBtn">How to Play</button><button id="settingsBtn">Settings</button></div><p class="compact center muted">Version ${v7} • HTML5 / CSS3 / vanilla JavaScript • separate local save slots</p></div></div>`,

  // ===== openworld/ui-map-actions.js =====
  // -- showWorldMapFilters --
  "openworld_ui_map_actions.showWorldMapFilters.001":'showWorldMapFilters',
  "openworld_ui_map_actions.showWorldMapFilters.002":(v0,v1,v2,v3)=>`<h2>World Map Filters</h2><div class="choice-list"><label><input type="checkbox" id="filterHostile" ${v0}> Hostile parties</label><label><input type="checkbox" id="filterFriendly" ${v1}> Friendly parties</label><label><input type="checkbox" id="filterNeutral" ${v2}> Neutral / wary parties</label><label><input type="checkbox" id="filterCompanions" ${v3}> Companion leads</label></div><div class="dialog-footer"><button id="filterDone">Done</button></div>`,
  // -- worldMapLegendHTML --
  "openworld_ui_map_actions.worldMapLegendHTML.001":`<div class="world-map-legend"><span><i class="legend-dot loc"></i>Place</span><span><b>✧</b> Discovery</span><span><i class="legend-dot hostile"></i>Hostile</span><span><i class="legend-dot neutral"></i>Neutral</span><span><i class="legend-dot friendly"></i>Friendly</span><span><i class="legend-dot lead"></i>Lead</span><span><i class="legend-dot escort"></i>Escort</span><span><b class="legend-pol">CTL</b> control</span><span><i class="legend-road open"></i>Open</span><span><i class="legend-road risky"></i>Risky</span><span><i class="legend-road dangerous"></i>Dangerous road</span></div>`,
  // -- regionTerrainHTML --
