  "openworld_ui_map_actions.openWorldMapHTML.001":(v0,v1,v2,v3,v4)=>`</div><div class="world-map-caption"><b>Day ${v0}</b><span>${v1}</span><span>${v2} moving parties • ${v3}</span></div></div>${v4}</div>`,
