  // -- liveBattleAlertHTML --
  "openworld_ui_map_actions.liveBattleAlertHTML.001":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10,v11)=>`<div class="panel live-battle-alert-panel"><h3>⚑ Guardian Caravan Stopped</h3><div class="warning notice"><b>${v0} has stopped ${v1}</b><br>Near ${v2} • ${v3} day${v4} away • unresolved through Day ${v5}${v6}${v7}${v8}</div><div class="choice-list compact"><button id="mainBattleIntervene">Go to Incident / Travel</button><button id="mainBattleMessenger" ${v9}>Dispatch Messenger</button><button id="mainBattleTrack" ${v10}>${v11}</button></div></div>`,
  "openworld_ui_map_actions.liveBattleAlertHTML.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9)=>`<div class="panel live-battle-alert-panel"><h3>⚔ Battle Underway</h3><div class="warning notice"><b>${v0} vs ${v1}</b><br>Near ${v2} • ${v3} day${v4} away • expected through Day ${v5}${v6}${v7}</div><div class="choice-list compact"><button id="mainBattleIntervene">Intervene / Travel</button><button id="mainBattleTrack" ${v8}>${v9}</button><button id="mainBattleIgnore">Ignore</button></div></div>`,

  "hall_staff_correspondence.homeNamedStaffDailyTick.001":(v0,v1,v2)=>`${v0}, ${v1}, improves to competence ${v2}/10 after a strong run of work.`,
  "hall_staff_correspondence.homeNamedStaffDailyTick.002":(v0,v1)=>`${v0}'s experience at Guardian Hall grows. Competence is now ${v1}/10.`,
  "hall_staff_correspondence.homeNamedStaffDailyTick.003":(v0,v1,v2)=>`${v0}, ${v1}, slips to competence ${v2}/10 after an extended period of poor performance.`,
  "hall_staff_correspondence.homeNamedStaffDailyTick.004":(v0,v1)=>`${v0}'s performance has regressed. Competence is now ${v1}/10.`,
  "hall_staff_correspondence.homeResolveNamedStaffRaise.001":(v0,v1)=>`${v0}'s salary request is approved. New salary: ${v1} gold / 14 days.`,
  "hall_staff_correspondence.homeResolveNamedStaffRaise.002":(v0)=>`${v0} resigns after the Guardian refuses the salary request.`,
  "hall_staff_correspondence.homeResolveNamedStaffRaise.003":(v0)=>`${v0} leaves Guardian Hall after a refused salary request.`,
  "hall_staff_correspondence.homeResolveNamedStaffRaise.004":(v0)=>`${v0} stays after the refusal, but the decision has clearly hurt morale and performance.`,
  "hall_staff_correspondence.homeRewardNamedStaff.001":(v0,v1,v2)=>`${v0} receives a voluntary raise of ${v1} gold. New salary: ${v2} gold / 14 days.`,
  "hall_staff_correspondence.homeRewardNamedStaff.002":'Hall Commendation Not Yet Available',
  "hall_staff_correspondence.homeRewardNamedStaff.003":'Guardian Hall has already held a Hall-wide staff commendation within the last 30 days.',
  "hall_staff_correspondence.homeRewardNamedStaff.004":(v0,v1)=>`${v0}, ${v1}, is formally recognized before the Hall household for excellent work.`,
  "hall_staff_correspondence.homeRewardNamedStaff.005":(v0,v1)=>`Guardian Hall publicly recognizes ${v0}, ${v1}, for excellent performance.`,
  "hall_staff_correspondence.homeFulfillProcurementFromStores.001":'Not Available in Hall Stores',
  "hall_staff_correspondence.homeFulfillProcurementFromStores.002":'Guardian Hall no longer has enough of the requested goods in storage.',
  "hall_staff_correspondence.homeFulfillProcurementFromStores.003":'Guardian Hall staff retrieved the requested item from storage',
  "hall_staff_correspondence.homeFulfillProcurementFromStores.004":(v0)=>`${v0} retrieved from Hall Stores`,
  "hall_staff_correspondence.homeFulfillProcurementFromStores.005":(v0)=>`Hall staff retrieve the requested goods directly from Guardian Hall Stores and deliver them to ${v0}. No outside procurement was necessary.`,
  "world_regions_security.dispatchGuardianCaravanMessenger.001":'Messenger Cannot Be Dispatched',
  "world_regions_security.dispatchGuardianCaravanMessenger.002":'The caravan incident is no longer waiting for a peaceful response.',
  "world_regions_security.dispatchGuardianCaravanMessenger.003":(v0,v1,v2)=>`Guardian Hall dispatches a messenger to ${v0}. The courier should reach the stopped caravan in about ${v1} day${v2}.`,
  "world_regions_security.dispatchGuardianCaravanMessenger.004":'Messenger Dispatched',
  "world_regions_security.dispatchGuardianCaravanMessenger.005":(v0,v1)=>`A Hall messenger is on the way. The incident will remain open long enough for the courier to arrive in about ${v0} day${v1}.`,
  "world_regions_security.dispatchGuardianCaravanMessenger.006":(v0,v1)=>`${v0} accepts the Hall messenger's explanation and clears ${v1} to continue.`,
