  "openworld_ui_map_actions.openWorldPlayerActionsHTML.001":(v0,v1,v2,v3,v4,v5)=>`<div class="panel player-actions-panel"><h3>Guardian & Company</h3><div class="choice-list compact player-action-grid"><button data-open="inventory"><b>Inventory</b><small>Equipment & items</small></button><button data-open="party"><b>Party</b><small>Roster & companions</small></button><button id="worldCompanyEconomy"><b>Company</b><small>Property & economy</small></button><button id="worldCharacterInfo"><b>Guardian</b><small>Stats & progression</small></button><button id="worldPrisoners"><b>Prisoners & Custody${v0}</b><small>${v1}</small></button>${v2}${v3}${v4}${v5}</div></div>`,
