  "openworld_ui_map_actions.showOpenWorldTravelMenu.001":'showOpenWorldTravelMenu',
  "openworld_ui_map_actions.showOpenWorldTravelMenu.002":(v0,v1,v2)=>`<h2>World & Travel</h2><p class="muted">Movement, crossings, and map controls. Regional party activity is listed under Region & Politics.</p><div class="choice-list"><button id="worldArea"><b>Explore / Inspect Area</b><small>${v0}</small></button><button id="worldRegionalTravelHub"><b>Regional Travel</b><small>${v1}</small></button>${v2}<button id="worldMapFilters"><b>Map Filters</b></button></div><div class="dialog-footer"><button class="closeModal">Back</button></div>`,
  // -- showOpenWorldCampingMenu --
  "openworld_ui_map_actions.showOpenWorldCampingMenu.001":'showOpenWorldCampingMenu',
  "openworld_ui_map_actions.showOpenWorldCampingMenu.002":'Camping Unavailable',
  "openworld_ui_map_actions.showOpenWorldCampingMenu.003":(v0)=>`The company is already in ${v0}. Use local lodging, Town Life, or Guardian Hall facilities instead.`,
  "openworld_ui_map_actions.showOpenWorldCampingMenu.004":(v0)=>`<h2>Camping — ${v0}</h2><p>Set up the company's field camp or review recent camp and road-life activity.</p><div class="choice-list"><button id="campMake"><b>Make Camp & Rest</b><small>Spend one day resting, recovering, and sharing the evening with the active company.</small></button><button id="campLife"><b>Camp & Road Life</b><small>Review recent camp scenes, companion moments, and road-life events.</small></button></div><div class="dialog-footer"><button class="closeModal">Back</button></div>`,
