  "openworld_ui_map_actions.showOpenWorldWorldLifeMenu.001":'showOpenWorldWorldLifeMenu',
  "openworld_ui_map_actions.showOpenWorldWorldLifeMenu.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9)=>`<h2>World Life</h2><p class="muted">People and relationships that continue moving while you travel.</p><div class="world-life-status"><span><b>${v0}</b> social event${v1}</span><span><b>${v2}</b> follow-up${v3}</span><span><b>${v4}</b> companion request${v5}</span><span><b>${v6}</b> messenger${v7}</span></div><div class="choice-list world-life-choice-list"><button id="worldLifeContacts"><b>Road Contacts</b><small>Recurring travelers, favors & grudges</small></button><button id="worldLifeSocial"><b>Social Life</b><small>Ongoing scenes and follow-ups</small></button><button id="worldLifePopulation"><b>Population & Movement</b><small>Resident moves, households & traveler bases</small></button><button id="worldLifeWork"><b>Personal Referrals & Requests</b><small>Referrals and messenger-delivered jobs</small></button><button id="worldLifeFactionPeople"><b>People & Faction Influence</b><small>${v8} local influence channel${v9}</small></button></div><div class="dialog-footer"><button class="closeModal">Back</button></div>`,
