  "openworld_ui_map_actions.showOpenWorldRecordsMenu.002":(v0,v1,v2,v3)=>`<h2>Journal & Contracts</h2><div class="choice-list"><button id="worldContractsJournal"><b>Contracts</b><small>${v0} ready • ${v1} active</small></button><button id="worldRegionalStories"><b>Regional Storylines</b><small>${v2} active • ${v3} resolved</small></button><button id="worldJournal"><b>World Journal</b><small>Priorities and records hub</small></button></div><div class="dialog-footer"><button class="closeModal">Back</button></div>`,
  // -- showOpenWorldRegionMenu --
  "openworld_ui_map_actions.showOpenWorldRegionMenu.001":'showOpenWorldRegionMenu',
  "openworld_ui_map_actions.showOpenWorldRegionMenu.002":(v0,v1,v2,v3,v4)=>`<h2>Region & Politics</h2>${v0}<div class="region-politics-hub"><section><h3>Region</h3><div class="choice-list"><button id="worldRegionOverview"><b>Region Overview</b><small>Settlements, prosperity, security, road pressure, and local problems.</small></button><button id="worldIntel"><b>Regional Intelligence (${v3})</b><small>Current reports, sightings, route knowledge, and other information the Guardian has actually learned.</small></button><button id="worldLaw"><b>Regional Law</b><small>Jurisdictions, warrants, bounties, restitution, and legal standing.</small></button><button id="worldStories"><b>Regional Stories (${v2})</b><small>Active regional storylines and completed outcomes.</small></button><button id="worldOpportunities"><b>Regional Opportunities (${v1})</b><small>Situations in the region where you can intervene.</small></button><button id="worldRegionalParties"><b>Regional Parties (${v4})</b><small>All active moving parties currently operating in this region.</small></button></div></section><section><h3>Politics</h3><div class="choice-list"><button id="worldPolitics"><b>Regional Politics</b><small>Settlement alignment, political issues, agreements, and recent changes.</small></button><button id="worldFactions"><b>Regional Factions</b><small>Faction standing, organized presence, diplomacy, and security activity.</small></button></div></section></div><div class="dialog-footer"><button class="closeModal">Back</button></div>`,
