  "world_road_travel.routeTravelOptions.001":'Direct Route',
  "world_road_travel.routeTravelOptions.002":(v0,v1,v2)=>`${v0} day${v1} • ${v2} road • normal encounter exposure`,
  "world_road_travel.routeTravelOptions.003":'Cautious Route',
