  "regions_sengia_redstone.showRedstoneCivicDecision.001":'showRedstoneCivicDecision',
  "regions_sengia_redstone.showRedstoneCivicDecision.002":(v0,v1,v2,v3,v4,v5)=>`<h2>${v0} — ${v1}</h2>${v2}<p>${v3}</p><div class="choice-list"><button data-redcivic="command"><b>${v4}</b><br><small>Strengthens formal Redstone authority.</small></button><button data-redcivic="civilian"><b>${v5}</b><br><small>Strengthens local/civilian authority.</small></button></div><div class="dialog-footer"><button id="redCivicBack">Back</button></div>`,
  // -- showSengiaDistrict --
  "regions_sengia_redstone.showSengiaDistrict.001":'showSengiaDistrict',
  "regions_sengia_redstone.showSengiaDistrict.002":'Merchants discuss provincial shortages, license fees, and which goods are being delayed by military loading priorities.',
  "regions_sengia_redstone.showSengiaDistrict.003":'Convoy manifests reveal where Sengia is pulling food, timber, tools, and manufactured goods from across the region.',
  "regions_sengia_redstone.showSengiaDistrict.004":'Petitioners challenge fines, requisitions, permits, delayed compensation, and jurisdiction decisions in public-facing offices.',
  "regions_sengia_redstone.showSengiaDistrict.005":'Officers coordinate patrols, couriers, stores, and convoy escorts while clerks convert operational urgency into formal orders.',
  "regions_sengia_redstone.showSengiaDistrict.006":(v0,v1,v2,v3,v4)=>`<h2>Sengia — ${v0}</h2><p>${v1}</p><div class="notice">${v2}</div><div class="stat-row"><span>District familiarity</span><b>${v3}</b></div><button id="sengiaDistrictSpend">${v4} (1 day)</button><div class="dialog-footer"><button id="sengiaDistrictBack">Back to Sengia</button></div>`,
  "regions_sengia_redstone.showSengiaDistrict.007":(v0)=>`Spent time in Sengia’s ${v0}`,
  "regions_sengia_redstone.showSengiaDistrict.008":'Spent time hearing public petitions',
  "regions_sengia_redstone.showSengiaDistrict.009":(v0)=>`${v0}. The company understands this part of Sengia better now.`,
