  "regions_sengia_redstone.redstoneInstitutionEffects.002":(v0,v1)=>`Food stock ${v0} • Local prosperity ${v1}`,
  "regions_sengia_redstone.redstoneInstitutionEffects.003":"Supply claims are now processed under the new policy, thanks to Cassian.",
  "regions_sengia_redstone.redstoneInstitutionEffects.004":'Workshop and fire-safety decisions now use the authority structure established during Ronan’s personal story.',
  // -- showRedstoneCivicLife --
  "regions_sengia_redstone.showRedstoneCivicLife.001":'showRedstoneCivicLife',
  "regions_sengia_redstone.showRedstoneCivicLife.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10,v11,v12)=>`<h2>${v0} — Civic Life</h2><p>${v1}</p>${v2}${v3}${v4}${v5}<button id="redstoneAuthority">Authority, Orders & Jurisdiction</button><button id="redstoneEconomy">Economy & Civilian Recovery</button><button id="redstoneSecurity">Military & Security</button>${v6}<h3>Institutions</h3><div class="redstone-institutions">${v7}</div><h3>People Living With These Decisions</h3><div class="choice-list compact">${v8}</div>${v9}${v10}<h3>Current Civic Question</h3>${v11}<h3>Recent Civic History</h3>${v12}<div class="dialog-footer"><button id="redstoneCivicBack">Back to Town Life</button></div>`,
