  "settlements_problems_stories.showPopulationMovementJournal.001":'showPopulationMovementJournal',
  "settlements_problems_stories.showPopulationMovementJournal.002":(v0,v1,v2,v3)=>`<h2>Population & Settlement Movement</h2><p>Named residents, households, and recurring road contacts can move as conditions and relationships change.</p><h3>Relocated Named Residents</h3>${v0}<h3>Households</h3>${v1}<h3>Established Road Contacts</h3>${v2}<h3>Recent Movement</h3>${v3}<div class="dialog-footer"><button class="closeModal">Back</button></div>`,
