  // -- showHomeDiningHistory --
  "hall_core_hospitality.showHomeDiningHistory.001":'showHomeDiningHistory',
  "hall_core_hospitality.showHomeDiningHistory.002":(v0)=>`<h2>Guardian Hall — Dining & Gathering Record</h2>${v0}<div class="dialog-footer"><button id="diningHistoryBack">Back to Dining Facilities</button></div>`,
  // -- showHomeDining --
  "hall_core_hospitality.showHomeDining.001":'showHomeDining',
  "hall_core_hospitality.showHomeDining.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10,v11,v12,v13,v14)=>`<h2>Guardian Hall — Dining, Gatherings & Banquets</h2><div class="two-col"><div class="card"><h3>Dining Hall</h3><p>Everyday company life, informal guests, celebrations, and larger social gatherings.</p><b>Capacity ${v0}</b><div class="choice-list compact"><button id="companySupper">Hold Company Supper</button>${v1}<button id="hostGathering" ${v2}>Host Hall Gathering</button>${v3}</div></div><div class="card"><h3>Formal Dining Room</h3><p>Honored guests, negotiations, private political dinners, and smaller deliberate gatherings.</p><b>Capacity ${v4}</b><div class="choice-list compact">${v5}<button id="hostFormalGathering" ${v6}>Host Formal Gathering</button></div></div></div><div class="notice compact"><b>Hall meal stores:</b> Food ${v7}/100 • Hospitality ${v8}/100<br><b>Outside gathering guests ready:</b> ${v9} • <b>Invitations still traveling:</b> ${v10}<br><small>Hall staff handle the meal from existing food and hospitality stores.</small></div><h3>Gathering Invitations</h3>${v11}${v12}<div class="dialog-toolbar"><button id="diningHistory">Dining & Gathering Record (${v13})</button></div>${v14}<div class="dialog-footer"><button id="diningBack">Back</button></div>`,
  "hall_core_hospitality.showHomeDining.003":'Elira Voss',
  "hall_core_hospitality.showHomeDining.004":'Large-household administration, guest service, and calm delegation',
  "hall_core_hospitality.showHomeDining.005":'Corven Hale',
  "hall_core_hospitality.showHomeDining.006":'Payroll, records, messenger traffic, and disciplined routines',
  "hall_core_hospitality.showHomeDining.007":'Mina Torr',
  "hall_core_hospitality.showHomeDining.008":'Kitchen, household morale, and practical hospitality',
  "hall_core_hospitality.showHomeDining.009":'Joren Pell',
  "hall_core_hospitality.showHomeDining.010":'Low-cost staffing, local hiring, and straightforward household work',
  "hall_core_hospitality.showHomeDining.011":'Cooks',
  "hall_core_hospitality.showHomeDining.012":'Prepare ordinary meals, guest service, and large-event food.',
