  "hall_staff_correspondence.homeHireSteward.001":(v0)=>`${v0} takes responsibility as Steward of Guardian Hall.`,
  "hall_staff_correspondence.homeHireSteward.002":(v0)=>`${v0} is appointed Steward of Guardian Hall.`,
  // -- homeChangeStaff --
