  // -- resolveHomeStaffIncident --
  "hall_staff_correspondence.resolveHomeStaffIncident.001":(v0,v1)=>`You authorize ${v0} gold for extra help and materials. ${v1} is handled without further disruption.`,
  "hall_staff_correspondence.resolveHomeStaffIncident.002":(v0)=>`${v0} resolves the matter within the authority of the Steward's office.`,
  "hall_staff_correspondence.resolveHomeStaffIncident.003":(v0)=>`${v0} contains the immediate problem, but the household remains strained and morale slips.`,
