  "hall_staff_correspondence.resolveHomeStaffIncident.005":'Household Matter Resolved',
  // -- maybeHomeStaffIncident --
  "hall_staff_correspondence.maybeHomeStaffIncident.001":'Kitchen Overtime',
  "hall_staff_correspondence.maybeHomeStaffIncident.002":'Several busy days have left the cooks covering meals, guests, and staff service without enough recovery time.',
  "hall_staff_correspondence.maybeHomeStaffIncident.003":'Messenger Backlog',
