  "hall_life_visitors_diplomacy.showHomeDelegationChooser.002":(v0)=>`<h2>Invite a Faction Delegation</h2><p>Guardian Hall can invite a recognized faction to private talks without implying endorsement or surrendering Hall autonomy.</p>${v0}<div class="dialog-footer"><button id="delegationBack">Back to Hall Politics</button></div>`,
  // -- homeAttemptMediation --
  "hall_life_visitors_diplomacy.homeAttemptMediation.001":'Mediation Not Yet Appropriate',
  "hall_life_visitors_diplomacy.homeAttemptMediation.002":(v0)=>`The Guardian Hall hosted a formal mediation recently. Another major mediation can be attempted in ${v0} day(s).`,
  "hall_life_visitors_diplomacy.homeAttemptMediation.003":'Hall Supplies Too Low',
  "hall_life_visitors_diplomacy.homeAttemptMediation.004":'A serious mediation requires enough food and hospitality reserve to receive both delegations properly.',
