  "hall_life_visitors_diplomacy.homeAttemptMediation.009":(v0)=>`The talks expose more hostility than common ground. Guardian Hall remains neutral, but relations between the two sides worsen to ${v0}.`,
  "hall_life_visitors_diplomacy.homeAttemptMediation.010":'The meeting is useful enough to keep both sides talking, but neither delegation is ready to make a meaningful concession.',
  "hall_life_visitors_diplomacy.homeAttemptMediation.011":(v0,v1,v2)=>`${v0} / ${v1} mediation: ${v2}`,
  "hall_life_visitors_diplomacy.homeAttemptMediation.012":(v0,v1,v2)=>`Guardian Hall hosts mediation between ${v0} and ${v1}. ${v2}`,
  "hall_life_visitors_diplomacy.homeAttemptMediation.013":'home politics',
  "hall_life_visitors_diplomacy.homeAttemptMediation.014":'Guardian Hall Mediation',
