  // -- homeAcceptEndorsementRequest --
  "hall_life_visitors_diplomacy.homeAcceptEndorsementRequest.001":(v0)=>`The Guardian publicly changed allegiance to ${v0}`,
  "hall_life_visitors_diplomacy.homeAcceptEndorsementRequest.002":`The Guardian announces a public endorsement from Guardian Hall`,
  "hall_life_visitors_diplomacy.homeAcceptEndorsementRequest.003":'Public endorsement announced at Guardian Hall',
  "hall_life_visitors_diplomacy.homeAcceptEndorsementRequest.004":(v0)=>`Public endorsement of ${v0} at Guardian Hall`,
  "hall_life_visitors_diplomacy.homeAcceptEndorsementRequest.005":(v0,v1)=>`The Guardian withdraws the prior public endorsement of ${v0} and publicly endorses ${v1}. The change is treated as a real shift in allegiance.`,
  "hall_life_visitors_diplomacy.homeAcceptEndorsementRequest.006":(v0)=>`The Guardian publicly endorses ${v0} from Guardian Hall.`,
