  "hall_life_visitors_diplomacy.generateHomeDiplomacyEvent.002":(v0)=>`${v0} Administrative Delegation`,
  "hall_life_visitors_diplomacy.generateHomeDiplomacyEvent.003":(v0)=>`Because ${v0} currently controls Shantium, its officials are requesting permission to inspect the Guardian Hall on a limited basis, and for the Hall to set aside space for ${v0} business.`,
  "hall_life_visitors_diplomacy.generateHomeDiplomacyEvent.004":(v0)=>`${v0} Political Delegation`,
  "hall_life_visitors_diplomacy.generateHomeDiplomacyEvent.005":(v0)=>`A ${v0} delegation asks the Guardian to turn private access into a public endorsement. They make clear that a friendly meeting alone is not what they came for.`,
  "hall_life_visitors_diplomacy.generateHomeDiplomacyEvent.006":(v0)=>`${v0} Claimant Delegation`,
  "hall_life_visitors_diplomacy.generateHomeDiplomacyEvent.007":(v0)=>`A frightened traveler has asked Guardian Hall for temporary sanctuary. A ${v0} delegation arrives soon afterward and demands that the Hall surrender the traveler to their custody.`,
  // -- homeDiplomacyDailyTick --
  "hall_life_visitors_diplomacy.homeDiplomacyDailyTick.001":(v0)=>`${v0} Delegation`,
  "hall_life_visitors_diplomacy.homeDiplomacyDailyTick.002":(v0)=>`A formal ${v0} delegation has arrived in response to the Guardian's invitation. They are prepared for private talks at Guardian Hall.`,
  "hall_life_visitors_diplomacy.homeDiplomacyDailyTick.003":(v0)=>`${v0} accepts the Hall's invitation and sends a delegation.`,
  // -- showHomeDiplomacy --
  "hall_life_visitors_diplomacy.showHomeDiplomacy.001":'showHomeDiplomacy',
  "hall_life_visitors_diplomacy.showHomeDiplomacy.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10,v11)=>`<h2>Guardian Hall — Politics & Diplomacy</h2><div class="hall-autonomy"><b>Hall status: Independent Guardian institution</b><br>${v0}</div><div class="notice hall-diplomacy-status"><b>Shantium control:</b> ${v1} • <b>Hall autonomy:</b> ${v2}/100<br><b>Public endorsement:</b> ${v3}<br><b>Mediations succeeded:</b> ${v4} • <b>Political meetings hosted:</b> ${v5}</div>${v6}<div class="choice-list"><button id="hallInviteDelegation" ${v7}><b>Invite Faction Delegation</b><small>Invite representatives for private talks.</small></button><button id="hallOfferMediation"><b>Offer Guardian Hall Mediation</b><small>Bring two factions to the Hall for mediation.</small></button>${v8}<button id="hallOpenAudiences"><b>Open Audiences & Visitors</b><small>${v9} political visitor${v10} waiting.</small></button><button id="hallAutonomyReview"><b>Review Hall Autonomy</b><small>Review autonomy and temporary access agreements.</small></button></div><h3>Recent Hall Diplomacy</h3><div class="hall-diplomacy-history">${v11}</div><div class="dialog-footer"><button id="hallPoliticsBack">Back</button></div>`,
  "hall_life_visitors_diplomacy.showHomeDiplomacy.003":'Guardian Hall Autonomy',

