  "hall_homecoming_office_upgrades.showHomecomingBriefing.002":(v0,v1,v2,v3)=>`<h2>Returned to Shantium — Guardian Hall Briefing</h2><p>The company has been away for <b>${v0} day${v1}</b>. Hall staff have prepared a summary of what changed.</p><h3>Needs Attention</h3>${v2}${v3}<div class="dialog-footer"><button id="homeBriefHall">Enter Guardian Hall</button><button id="homeBriefContinue">Return to Open World</button></div>`,
  // -- homeHomecomingSummaryHTML --
  "hall_homecoming_office_upgrades.homeHomecomingSummaryHTML.001":(v0,v1,v2,v3)=>`<div class="notice homecoming-main-alert"><b>Guardian Hall homecoming briefing ready</b><br><small>${v0} day${v1} away • ${v2} matter${v3} flagged</small><br><button id="worldHomecomingBrief">Review Hall Briefing</button></div>`,
  // -- showGuardianOffice --
  "hall_homecoming_office_upgrades.showGuardianOffice.001":'showGuardianOffice',
  "hall_homecoming_office_upgrades.showGuardianOffice.002":(v0,v1)=>`${v0} homecoming matter${v1} waiting`,
  "hall_homecoming_office_upgrades.showGuardianOffice.003":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10,v11,v12)=>`<h2>Guardian Office</h2><p>Your officers bring reports, correspondence, and Hall business here.</p><div class="notice"><b>Day ${v0}</b> • ${v1}<br><b>Correspondence:</b> ${v2} unread • <b>Special requests:</b> ${v3}<br><b>Hall budget:</b> ${v4} gold • <b>Security:</b> ${v5} • <b>Household:</b> ${v6}${v7}${v8}${v9}</div>${v10}<div class="choice-list">${v11}<button id="officeMail"><b>Correspondence & Requests</b><small>Messages, inquiries, and special requests.</small></button><button id="officeLogistics"><b>Logistics</b><small>Supplies, shipments, and purchasing.</small></button><button id="officeBudget"><b>Hall Budget</b><small>Income, expenses, and available funds.</small></button><button id="officeBusiness"><b>Hall Business</b><small>Trade and paid work directed by the Economic Adviser.</small></button><button id="officeStaff"><b>Staff & Household</b><small>Steward, staffing, payroll, and household matters.</small></button>${v12}</div><div class="dialog-footer"><button id="officeBack">Back</button></div>`,
