  "hall_homecoming_office_upgrades.homeRunTrainingDay.002":'Training Yard',
  "hall_homecoming_office_upgrades.homeRunTrainingDay.003":(v0,v1)=>`Another full company training day will be worthwhile in ${v0} day${v1}.`,
