  "hall_homecoming_office_upgrades.homeRunTrainingDay.007":(v0)=>`The company spends the day drilling movement, weapons, field communication, and class practice. Campaign XP increases by ${v0}; participants finish with 10 less Stamina.`,
  // -- showHomeTrainingYard --
  "hall_homecoming_office_upgrades.showHomeTrainingYard.001":'showHomeTrainingYard',
  "hall_homecoming_office_upgrades.showHomeTrainingYard.002":'trainingYard',
  "hall_homecoming_office_upgrades.showHomeTrainingYard.003":(v0,v1,v2,v3,v4,v5,v6,v7)=>`<h2>Guardian Hall — ${v0}</h2><p>Use the yard for full-company drills, weapons practice, and paid instruction.</p><div class="notice"><b>Level ${v1}/${v2} • ${v3} company members available</b><br><small>A training day grants campaign XP and takes one day. It can be repeated every ${v4} days.</small></div><div class="choice-list"><button id="yardTrain" ${v5}>${v6}</button></div><h3>Company</h3>${v7}<div class="dialog-footer"><button id="yardBack">Back</button></div>`,
  // -- showHomeArchives --
