  "hall_homecoming_office_upgrades.showHomeArchives.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8)=>`<h2>Guardian Hall — ${v0}</h2><p>Campaign records, correspondence, political decisions, travel reports, and Hall records are kept here in Shantium.</p><div class="notice"><b>Level ${v1}/${v2} • ${v3} campaign records • ${v4} archived message${v5}</b><br><small>${v6}</small></div><h3>Recent Campaign Record</h3>${v7}<h3>Archived Correspondence</h3>${v8}<div class="dialog-footer"><button id="archivesBack">Back</button></div>`,
  // -- showHomeInfirmary --
  "hall_homecoming_office_upgrades.showHomeInfirmary.001":'showHomeInfirmary',
  "hall_homecoming_office_upgrades.showHomeInfirmary.002":'infirmaryWing',
  "hall_homecoming_office_upgrades.showHomeInfirmary.003":(v0,v1,v2,v3)=>`<h2>Guardian Hall — Expanded Infirmary</h2><p>The infirmary wing has beds and treatment space for the active company and reserve companions.</p><div class="notice"><b>Medical reserve:</b> ${v0}/100 • <b>Medical staff:</b> ${v1}<br><small>A full-company convalescent day uses ${v2} medical reserve and one day.</small></div><div class="choice-list"><button id="infirmaryTreat" ${v3}>Full-Company Convalescent Day</button></div><div class="dialog-footer"><button id="infirmaryBack">Back</button></div>`,
