  "hall_homecoming_office_upgrades.buyHomeUpgrade.001":'Hall improvement',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.002":(v0,v1)=>`${v0} Level ${v1}.`,
  "hall_homecoming_office_upgrades.buyHomeUpgrade.003":'trophyWall',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.004":'Guardian Hall opens a public trophy and chronicle wall',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.005":'warRoom',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.006":'guestQuarters',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.007":'guestQuarters',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.008":'diningExpansion',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.009":'diningExpansion',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.010":'diningExpansion',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.011":'hallSecurity',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.012":'hallSecurity',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.013":'hallSecurity',
  "hall_homecoming_office_upgrades.buyHomeUpgrade.014":(v0)=>`${v0} is completed. Hall guards review gates, holding security, alarms, and defensive positions.`,
