  "companions_stories_settlement_services.showSettlementServices.001":'showSettlementServices',
  "companions_stories_settlement_services.showSettlementServices.002":'Services Refused',
  "companions_stories_settlement_services.showSettlementServices.003":(v0,v1)=>`${v0} is controlled by ${v1}, and your current standing is too hostile for merchants or hosts to serve the company.`,
  "companions_stories_settlement_services.showSettlementServices.004":`<section class="service-section"><div class="service-section-heading"><h3>Market & Shops</h3><small>Shantium’s specialist merchants and artisans</small></div><div class="service-button-grid"><button data-serviceopen="market"><b>Market District</b><small>General market, jewelry & resale</small></button><button data-serviceopen="blacksmith"><b>Blacksmith</b><small>Melee weapons & armor</small></button><button data-serviceopen="fletcher"><b>Fletcher</b><small>Bows, crossbows & ranged gear</small></button><button data-serviceopen="wizard"><b>Wizards Guild</b><small>Magical equipment</small></button><button data-serviceopen="enchanter"><b>Enchanter</b><small>Permanent item enchantments</small></button><button data-serviceopen="apothecary"><b>Apothecary</b><small>Consumables & supplies</small></button><button id="settlementTrade"><b>Trade Goods</b><small>Regional cargo market</small></button><button id="settlementEconomy"><b>Property & Investment</b><small>Company holdings in Shantium</small></button></div></section>`,
  "companions_stories_settlement_services.showSettlementServices.005":(v0,v1)=>`<section class="service-section"><div class="service-section-heading"><h3>Market & Equipment</h3><small>Local trade and regionally appropriate stock</small></div><div class="service-button-grid"><button id="settlementTrade"><b>Trade Goods</b><small>Buy, sell & inspect local prices</small></button><button id="settlementGear"><b>Local Equipment</b><small>${v0} item${v1} available</small></button><button id="settlementEconomy"><b>Property & Investment</b><small>Local long-term holdings</small></button></div></section>`,
  "companions_stories_settlement_services.showSettlementServices.006":(v0,v1,v2,v3,v4,v5)=>`<section class="service-section"><div class="service-section-heading"><h3>Stay & Recovery</h3><small>Rest, lodging and medical care</small></div><div class="service-button-grid"><button id="settlementInn"><b>${v0} — ${v1}g</b><small>Advance 1 day • restore HP/Stamina • traveler news</small></button><button id="settlementHeal" ${v2}><b>${v3}</b><small>${v4}</small></button>${v5}</div></section>`,
  "companions_stories_settlement_services.showSettlementServices.007":`<section class="service-section"><div class="service-section-heading"><h3>Training</h3><small>Guardian development and combat preparation</small></div><div class="service-button-grid"><button data-serviceopen="training"><b>Training Yard</b><small>Attributes, class progression & combat guidance</small></button></div></section>`,
  "companions_stories_settlement_services.showSettlementServices.008":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10,v11,v12,v13,v14)=>`<h2>${v0} — Market & Services</h2>${v1}<p>${v2} • controlled by <b>${v3}</b></p><div class="notice compact">Security <b>${v4}</b> • Prosperity <b>${v5}</b> • Local reputation <b>${v6}</b></div>${v7}${v8}${v9}${v10}${v11}${v12}${v13}${v14}<div class="dialog-footer"><button id="servicesLaw">Law / Local Record</button><button class="closeModal">Close</button></div>`,
  "companions_stories_settlement_services.showSettlementServices.009":(v0)=>`Stayed as an honored guest in ${v0}`,
  "companions_stories_settlement_services.showSettlementServices.010":'Local Hospitality',
  "companions_stories_settlement_services.showSettlementServices.011":'Residents insist the company stay as guests tonight. No charge.',
  "companions_stories_settlement_services.showSettlementServices.012":'Local Care',
