  "exploration_wilderness_artifacts.showWildernessSite.002":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10,v11)=>`<h2>${v0}</h2><p>${v1}</p>${v2}${v3}<div class="notice"><b>${v4} site</b> • Discovered Day ${v5} • Visits ${v6}<br>Status: ${v7}</div>${v8}<div class="choice-list"><button id="siteInterior">${v9}</button><button id="siteSearch">${v10}</button><button id="siteObserve">Study the Surroundings</button><button id="siteRoadLife">Ask Companions What They Think</button></div><p class="muted">Progress inside this site is saved when you leave.</p><div class="dialog-footer">${v11}<button class="closeModal">Close</button></div>`,
