  "companions_life_road.roadLifeInitiativeSummary.001":'Ranger',
  "companions_life_road.roadLifeInitiativeSummary.002":'Rogue',
  "companions_life_road.roadLifeInitiativeSummary.003":(v0,v1)=>`${v0} points out a route, trail, or overlook near ${v1} that might be worth checking before the company moves on.`,
  "companions_life_road.roadLifeInitiativeSummary.004":'Healer',
  "companions_life_road.roadLifeInitiativeSummary.005":(v0,v1)=>`${v0} wants to use the pause near ${v1} to check injuries, supplies, and who is hiding fatigue.`,
  "companions_life_road.roadLifeInitiativeSummary.006":'Vanguard',
  "companions_life_road.roadLifeInitiativeSummary.007":'Warden',
  "companions_life_road.roadLifeInitiativeSummary.008":'Berserker',
  "companions_life_road.roadLifeInitiativeSummary.009":(v0,v1)=>`${v0} suggests using the stop near ${v1} for a short company drill. It beats standing around doing nothing.`,
  "companions_life_road.roadLifeInitiativeSummary.010":(v0,v1)=>`${v0} proposes a deliberate pause near ${v1} and has a specific idea for how to use it.`,
