  "companions_life_road.attemptPersistentRecruit.003":'Companion Joined',
  "companions_life_road.attemptPersistentRecruit.004":(v0)=>`${v0} joined the Guardian after being sought out in the wider region.`,
  "companions_life_road.attemptPersistentRecruit.005":'Companion Recruited',
