  "companions_life_road.attemptPersistentRecruit.008":(v0)=>`${v0} declines. They continue on their own path and may be willing to talk again later.`,

  // ===== ui/game-town-navigation.js =====
  // -- renderGame --
  "ui_game_town_navigation.renderGame.001":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10)=>`<div class="app-shell"><div class="titlebar"><div class="left" id="hudTitleLeft">${v0} • Level ${v1} • ${v2} gold</div><div>SIEGE OF SHANTIUM</div><div class="right"><span id="hudRound">Round ${v3}/${v4}</span><button id="menuBtn">Menu</button></div></div><div class="game-grid"><div class="sidebar"><div class="panel" id="hudGuardian">${v5}</div><div class="panel"><h3>Actions</h3><div class="choice-list"><button data-open="hall">Guardian Hall</button><button data-open="inventory">Inventory / Equipment</button><button data-open="party">Party / Roster</button><button id="endRoundBtn">End Siege Round</button></div><div class="notice compact">Actions remaining: <b id="hudActions">${v6}</b><br>Intercepting an enemy uses 1 action. Most town visits are free.</div></div></div><div class="panel map-panel" id="hudMap">${v7}</div><div class="sidebar"><div class="panel" id="hudTown">${v8}</div><div class="panel"><h3>Town Locations</h3><div class="town-atmosphere">${v9}</div><div class="choice-list compact"><button data-open="blacksmith">Blacksmith</button><button data-open="fletcher">Fletcher</button><button data-open="wizard">Wizards Guild</button><button data-open="market">Market District</button><button data-open="enchanter">Enchanter</button><button data-open="apothecary">Apothecary</button><button data-open="healer">Temple / Healer</button><button data-open="tavern">Tavern</button><button data-open="training">Training Yard</button><button data-open="mason">Carpenter / Mason</button><button data-open="storehouse">Storehouse</button><button data-open="council">Council Hall</button><button data-open="townlife">Town Life</button><button data-open="chronicle">Siege Chronicle</button></div></div></div><div class="panel log-panel"><h3>Chronicle</h3><div class="log">${v10}</div></div></div></div>`,
