  "ui_game_town_navigation.guardianPanel.001":(v0,v1,v2,v3,v4,v5,v6,v7,v8,v9,v10,v11,v12,v13,v14,v15,v16,v17,v18,v19,v20,v21)=>`${v0}<div class="stat-row"><span>Class</span><b>${v1}</b></div><div class="stat-row"><span>HP</span><b>${v2}/${v3}</b></div><div class="meter hp"><span style="width:${v4}%"></span></div><div class="stat-row"><span>Stamina</span><b>${v5}/${v6}</b></div><div class="meter stamina"><span style="width:${v7}%"></span></div><div class="stat-row"><span>XP</span><b>${v8}/${v9}</b></div><div class="stat-row"><span>Might</span><b>${v10}</b></div><div class="stat-row"><span>Finesse</span><b>${v11}</b></div><div class="stat-row"><span>Fortitude</span><b>${v12}</b></div><div class="stat-row"><span>Focus</span><b>${v13}</b></div><div class="stat-row"><span>Agility</span><b>${v14}</b></div><div class="stat-row"><span>Presence</span><b>${v15}</b></div><div class="stat-row"><span>Defense</span><b>${v16}</b></div><div class="stat-row" title="Scouting improves pursuit, ambush planning, road intelligence, and several exploration/encounter checks."><span>Scouting</span><b>${v17}</b></div><div class="stat-row"><span>Weapon</span><b>${v18}</b></div><h3 class="party-hud-title">Active Party ${v19}/${v20}</h3>${v21}`,
