  "siege_round_events_endings.showDefenseAssignments.003":(v0,v1,v2)=>`<h2>Siege Defense Assignments</h2><p>Reserve companions can defend Shantium while the active company operates in the field.</p><div class="notice"><b>Current reserve contribution:</b> +${v0} defense power${v1}</div>${v2}<div class="dialog-footer"><button id="defenseDone">Done</button></div>`,
